#include <vector>
#include <utility>

void demonstrate_swap_safety() noexcept {
    std::vector<int> v1(1000); 
    std::vector<int> v2(1);

    // Member swap is guaranteed not to throw, regardless of content size
    v1.swap(v2);

    // std::swap will delegate to the member swap for standard containers
    std::swap(v1, v2);

    // The entire memory block representing v1's old data is now owned by v2,
    // and vice versa, without any risk of exception.
}
